  "concepts": [],
  "definitions": [],
  "explanations": [
    {
      "topic": {
        "text": "switch statement versus if statement for role-based messages",
        "refs": ["Q0001"]
      },
      "explanation_text": {
        "text": "A switch statement can be used instead of an if statement to compare the value of a variable (e.g., role) against multiple constant cases, which may look cleaner.",
        "refs": ["Q0001"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "break statement in a switch block",
        "refs": ["Q0002", "Q0003"]
      },
      "explanation_text": {
        "text": "A break statement is required after each case clause to exit the switch block; without it, execution falls through to subsequent cases.",
        "refs": ["Q0002", "Q0003"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "default clause in a switch statement",
        "refs": ["Q0002"]
      },
      "explanation_text": {
        "text": "A default clause executes when none of the preceding case values match the variable.",
        "refs": ["Q0002"]
      },
      "explanation_type": null
    }
  ],
  "examples": [],
  "facts": [
    {
      "fact_text": {
        "text": "If the role is \"admin\", the program should print \"you are an admin\".",
        "refs": ["Q0000", "Q0001"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "If the role is \"moderator\", the program should print \"you are a moderator\".",
        "refs": ["Q0000", "Q0002"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "If the role matches none of the specified cases, the program should print \"you are a guest\".",
        "refs": ["Q0000", "Q0002", "Q0003"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "When using a switch statement with string values, a compilation error occurs if the variable type does not match the case label types.",
        "refs": ["Q0004"]
      },
      "fact_type": null
    }
  ],
  "formulas": [],
  "procedures": [
    {
      "procedure_name": {
        "text": "Implement role-based messaging with a switch statement",
        "refs": ["Q0001"]
      },
      "steps": [
        {
          "text": "Write the switch keyword followed by parentheses containing the variable (e.g., role).",
          "refs": ["Q0001"]
        },
        {
          "text": "Open a block and add case clauses for each role value (admin, moderator, etc.) ending each with a colon.",
          "refs": ["Q0001", "Q0002"]
        },
        {
          "text": "Inside each case, add the print statement for the corresponding message.",
          "refs": ["Q0002"]
        },
        {
          "text": "Add a break statement after each case to exit the switch block.",
          "refs": ["Q0002", "Q0003"]
        },
        {
          "text": "Optionally add a default clause to handle any unmatched role values and print a guest message.",
          "refs": ["Q0002"]
        }
      ],
      "prerequisites": null,
      "outcomes": null,
      "content": {
        "text": "This procedure demonstrates how to replace multiple if‑else checks with a switch statement for role handling.",
        "refs": ["Q0001", "Q0002", "Q0003"]
      }
    }
  ],
